import React from 'react';

import { TimePeriodType } from 'utils/timePeriod/timePeriodAvailability';

import { SliderAreaContainer } from '../../TimePeriodSelector.styles';
import { computeSliderPositions } from '../../utils';
import { QuarterBrackets } from '../QuarterBrackets';
import { StaticMonthLabels } from '../StaticMonthLabels';
import { TimePeriodSliderTrack } from '../TimePeriodSliderTrack';

const CLOSED_MONTH_INDEX = 11;
const FULL_YEAR_POSITIONS = computeSliderPositions(
  TimePeriodType.FY,
  null,
  CLOSED_MONTH_INDEX,
);

export function TimePeriodFullYearSlider() {
  return (
    <SliderAreaContainer data-testid="time-period-fy-slider">
      <TimePeriodSliderTrack
        positions={FULL_YEAR_POSITIONS}
        showHandle={false}
      />
      <StaticMonthLabels />
      <QuarterBrackets
        getState={(quarter) => ({
          active: false,
          disabled: true,
          muted: true,
          ariaLabel: `${quarter} unavailable for Full Year`,
        })}
      />
    </SliderAreaContainer>
  );
}
